const FACTS={"Bacteroides":"One of the most abundant gut genera \u2014 versatile fibre and protein degraders that help train the immune system.","Faecalibacterium":"A major butyrate producer (F. prausnitzii); low levels are repeatedly linked to inflammation and IBD.","Phocaeicola":"Recently split off from Bacteroides (e.g. P. vulgatus); a core fibre-fermenter in most guts.","Prevotella":"Thrives on plant fibre and is abundant in people eating high-fibre, non-industrialized diets.","Roseburia":"A motile butyrate producer that ferments dietary fibre and helps nourish the gut lining.","Blautia":"A common acetate producer associated with a balanced microbiome and lower visceral fat.","Bifidobacterium":"The classic 'probiotic' genus \u2014 dominant in breastfed infants and used in many fermented foods.","Eubacterium":"A diverse group of fermenters; several species make butyrate and transform bile acids.","Alistipes":"Bile-tolerant fermenters that produce succinate and acetate; associated with protein-rich diets.","Akkermansia":"A. muciniphila lives in the mucus layer and is linked to a healthy gut barrier and metabolism.","Ruminococcus":"Specialists at breaking down resistant starch and complex fibres that other microbes can't touch.","Agathobacter":"Contains A. rectalis (formerly Eubacterium rectale), one of the gut's top butyrate producers.","Parabacteroides":"Bile-acid-modifying fermenters; some species are being explored for metabolic benefits.","Veillonella":"Unusual for using lactate \u2014 from other microbes or from exercise \u2014 as its main fuel.","Parasutterella":"A core but enigmatic resident involved in bile-acid and amino-acid metabolism.","Lachnospira":"A pectin-degrading fibre specialist from the Lachnospiraceae family.","Christensenella":"Highly heritable and consistently associated with leanness and long-term gut health.","Gemmiger":"A butyrate-producing relative of Faecalibacterium common in healthy adults.","Lactobacillus":"Lactic-acid bacteria found in yogurt and fermented foods, and used widely as probiotics.","Barnesiella":"Fibre-fermenting Bacteroidetes that can help resist colonisation by pathogens.","Adlercreutzia":"Converts dietary plant lignans and isoflavones into bioactive compounds such as equol.","Methanobrevibacter":"An archaeon (not a bacterium) \u2014 M. smithii recycles hydrogen into methane in the gut.","Streptococcus":"A large genus of sugar-fermenters; oral and gut species produce lactic acid.","Catenibacterium":"A sugar-fermenter more common in high-fibre, non-industrialized diets.","Escherichia":"Includes E. coli \u2014 mostly harmless gut residents, though some strains can cause disease.","Klebsiella":"Opportunistic Enterobacteria; blooms can accompany inflammation or antibiotic use.","Anaerostipes":"Converts lactate and sugars into butyrate, linking different microbes' metabolism.","Desulfovibrio":"A sulfate-reducer that produces hydrogen-sulfide gas as a by-product.","Butyricicoccus":"Named for its butyrate production; studied for helping protect the gut barrier.","Oscillospira":"Long-uncultured and mysterious; associated with leanness and fibre-rich diets.","Odoribacter":"Produces butyrate and other short-chain fatty acids; often reduced in inflammatory conditions.","Bilophila":"A bile-loving sulfate-reducer that increases on high-fat, high-meat diets.","Intestinibacter":"A spore-former tied to gut bile-acid metabolism; shifts with diet and disease.","Fusobacterium":"Mostly oral bacteria; some species draw research attention in colorectal health.","Paraprevotella":"A Prevotella relative that ferments dietary fibre into short-chain fatty acids.","Dorea":"A hydrogen-producing fermenter from the Lachnospiraceae family.","Clostridium":"A huge, diverse genus \u2014 most gut species are harmless fermenters, a few are pathogens.","Dialister":"Small, fastidious fermenters found in both the mouth and the gut.","Eggerthella":"Transforms dietary polyphenols and bile acids into bioactive metabolites.","Phascolarctobacterium":"First found in the koala; uses succinate to make propionate in the gut.","Collinsella":"An Actinobacterium whose levels shift with dietary fibre and cholesterol metabolism.","Haemophilus":"Mostly respiratory-tract bacteria; minor sugar-fermenting members appear in the gut.","Enterococcus":"Hardy gut bacteria used in some probiotics but also known for antibiotic resistance.","Coprococcus":"A butyrate producer repeatedly associated with quality of life and mood in studies.","Mediterraneibacter":"Reclassified from Ruminococcus (e.g. M. gnavus); a mucin-degrading fermenter.","Holdemanella":"A fibre-fermenter producing short-chain fatty acids with possible anti-inflammatory effects.","Subdoligranulum":"A close relative of Faecalibacterium and a butyrate producer in healthy guts.","Sutterella":"A common, mildly pro-inflammatory resident that interacts with the gut immune system.","Fusicatenibacter":"A Lachnospiraceae fibre-fermenter often reduced during gut inflammation.","Romboutsia":"A spore-forming gut resident whose abundance tracks with diet and gut health."};

function mulberry32(a){
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const SEED = 20260601;            // fixed constant -> identical data every load
const rng = mulberry32(SEED);
const rand = () => rng();
function gauss(){ // Box–Muller using the seeded rng
  let u=0,v=0; while(u===0)u=rng(); while(v===0)v=rng();
  return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
}
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const round=(x,d=2)=>{const p=Math.pow(10,d);return Math.round(x*p)/p;};
function percentileOf(sortedAsc, value){
  let lo=0; for(let i=0;i<sortedAsc.length;i++){ if(sortedAsc[i]<=value) lo=i+1; else break; }
  return Math.round(100*lo/sortedAsc.length);
}
function quantile(sortedAsc,q){
  const pos=(sortedAsc.length-1)*q, base=Math.floor(pos), rest=pos-base;
  return sortedAsc[base+1]!==undefined ? sortedAsc[base]+rest*(sortedAsc[base+1]-sortedAsc[base]) : sortedAsc[base];
}
const fmt = n => (Math.round(n*10)/10).toLocaleString();

