const REGIONS=["North America","Europe","Asia","South America","Oceania","Africa","Other"];
const REGION_W=[0.42,0.24,0.12,0.07,0.05,0.05,0.05];
const SEXES=["Female","Male","Other","No response"];
const SEX_W=[0.53,0.42,0.025,0.025];
function weightedPick(items,weights){
  const r=rng(); let c=0; for(let i=0;i<items.length;i++){ c+=weights[i]; if(r<=c) return items[i]; } return items[items.length-1];
}
function generateCohort(N=600){
  const people=[];
  for(let i=0;i<N;i++){
    const plant_count = clamp(Math.round(14 + gauss()*8 + (rng()<.12? 14:0)),0,40);
    const water_l     = round(clamp(1.4 + gauss()*0.55 + plant_count*0.012,0,3),2);
    const exercise_freq = clamp(Math.round(3 + gauss()*1.8),0,7);
    const sleep_hours = round(clamp(7.1 + gauss()*0.95,4,10),1);
    const fiber_score = clamp(Math.round(plant_count*1.7 + gauss()*14 + 18),0,100);
    const age = clamp(Math.round(42 + gauss()*16 + (rng()<.06? -28:0)),1,90);
    const region = weightedPick(REGIONS,REGION_W);
    const sex = weightedPick(SEXES,SEX_W);
    // diversity correlated w/ plants + fiber, mild age effect
    const shannon = round(clamp(
        3.28 + plant_count*0.030 + fiber_score*0.008 + exercise_freq*0.03
        + (age>3? 0:-1.3) + gauss()*0.46, 2.4, 8.0),2);
    // PCA: axis1 driven by industrialization/fiber, axis2 noise + region
    const ind_base = region==="Africa"||region==="Asia"? 38: region==="South America"? 55: 78;
    const industrialization_score = clamp(Math.round(ind_base + gauss()*12 - fiber_score*0.06),0,100);
    const pca1 = round(-2.2 + (industrialization_score-50)*0.05 + gauss()*0.5,3);
    const pca2 = round((fiber_score-50)*0.03 + gauss()*0.7,3);
    // microbiome age: tracks chronological age but pulled younger by diversity/fiber
    const microbiome_age = clamp(Math.round(age - (shannon-4.5)*5 - (fiber_score-50)*0.12 + gauss()*5),1,95);
    // log-ratios for taxon pairs (higher fiber -> more Faecalibacterium vs Proteobacteria etc.)
    const lr_faecali_proteo = round( 0.4 + fiber_score*0.02 - industrialization_score*0.01 + gauss()*0.7, 2);
    const lr_prevotella_bacteroides = round( (fiber_score-50)*0.03 - (industrialization_score-50)*0.02 + gauss()*0.9, 2);
    const lr_firmicutes_bacteroidetes = round( 0.2 + (age-42)*0.006 + gauss()*0.6, 2);
    const lr_akkermansia_ecoli = round( 0.1 + exercise_freq*0.07 + fiber_score*0.008 + gauss()*0.7, 2);
    people.push({
      id:i, plant_count, water_l, exercise_freq, sleep_hours, fiber_score, age, region, sex,
      shannon, pca1, pca2, microbiome_age, industrialization_score,
      lr_faecali_proteo, lr_prevotella_bacteroides, lr_firmicutes_bacteroidetes, lr_akkermansia_ecoli,
      // synthetic nutrient intakes (for similarity scatter)
      protein_g: clamp(Math.round(70 + gauss()*22),20,160),
      sugar_g: clamp(Math.round(80 - fiber_score*0.3 + gauss()*25),10,200),
      fat_g: clamp(Math.round(70 + gauss()*20),20,150)
    });
  }
  return people;
}
const COHORT = generateCohort(600);
const N = COHORT.length;

