const NS="http://www.w3.org/2000/svg";
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

function scaleLinear(domain,range){
  const [d0,d1]=domain,[r0,r1]=range, m=(r1-r0)/((d1-d0)||1);
  const f=v=>r0+(v-d0)*m; f.invert=p=>d0+(p-r0)/m; f.domain=domain; f.range=range; return f;
}
function niceTicks(min,max,count=5){
  const span=(max-min)||1, step0=span/count, mag=Math.pow(10,Math.floor(Math.log10(step0)));
  const norm=step0/mag, step=(norm>=7.5?10:norm>=3.5?5:norm>=1.5?2:1)*mag;
  const start=Math.ceil(min/step)*step, t=[];
  for(let v=start; v<=max+1e-9; v+=step) t.push(round(v,6));
  return t;
}
// axis renderer: ticks + labels + optional title
function axis(scale,opts){
  const {orient,pos,ticks,len,title,fmt=(d=>d),tickLen=5}=opts; let s='';
  if(orient==='bottom'){
    s+=`<line x1="${scale.range[0]}" y1="${pos}" x2="${scale.range[1]}" y2="${pos}" stroke="#40454d"/>`;
    ticks.forEach(t=>{ const x=scale(t);
      s+=`<line x1="${x}" y1="${pos}" x2="${x}" y2="${pos+tickLen}" stroke="#40454d"/>`;
      s+=`<text x="${x}" y="${pos+tickLen+13}" text-anchor="middle" font-size="11" fill="#86868b">${esc(fmt(t))}</text>`;
    });
    if(title) s+=`<text x="${(scale.range[0]+scale.range[1])/2}" y="${pos+tickLen+30}" text-anchor="middle" font-size="11.5" font-weight="700" fill="#a1a1a6">${esc(title)}</text>`;
  } else { // left
    s+=`<line x1="${pos}" y1="${scale.range[0]}" x2="${pos}" y2="${scale.range[1]}" stroke="#40454d"/>`;
    ticks.forEach(t=>{ const y=scale(t);
      s+=`<line x1="${pos-tickLen}" y1="${y}" x2="${pos}" y2="${y}" stroke="#40454d"/>`;
      s+=`<text x="${pos-tickLen-5}" y="${y+4}" text-anchor="end" font-size="11" fill="#86868b">${esc(fmt(t))}</text>`;
    });
    if(title) s+=`<text transform="translate(${pos-tickLen-34},${(scale.range[0]+scale.range[1])/2}) rotate(-90)" text-anchor="middle" font-size="11.5" font-weight="700" fill="#a1a1a6">${esc(title)}</text>`;
  }
  return s;
}
function gridH(scale,ticks,x0,x1){ // horizontal gridlines for a left scale
  return ticks.map(t=>`<line x1="${x0}" y1="${scale(t)}" x2="${x1}" y2="${scale(t)}" stroke="#1e2126"/>`).join('');
}
// deterministic jitter per index (so it doesn't change on re-render)
function jitter(i,amp){ const r=mulberry32(SEED+ i*2654435761>>>0)(); return (r-0.5)*2*amp; }
// histogram binning
function histogram(values,binCount,domain){
  const [lo,hi]=domain||[Math.min(...values),Math.max(...values)];
  const w=(hi-lo)/binCount, bins=Array.from({length:binCount},(_,i)=>({x0:lo+i*w,x1:lo+(i+1)*w,n:0}));
  values.forEach(v=>{ let k=Math.floor((v-lo)/w); if(k<0)k=0; if(k>=binCount)k=binCount-1; bins[k].n++; });
  return bins;
}
// simple gaussian KDE -> polyline points across [lo,hi]
function kde(values,lo,hi,steps=48,bw){
  const n=values.length, h=bw|| (1.06*std(values)*Math.pow(n,-1/5))||1;
  const xs=[],ys=[];
  for(let i=0;i<=steps;i++){ const x=lo+(hi-lo)*i/steps; let s=0;
    for(const v of values){ const u=(x-v)/h; s+=Math.exp(-0.5*u*u); }
    xs.push(x); ys.push(s/(n*h*Math.sqrt(2*Math.PI)));
  }
  return {xs,ys};
}
function std(a){ const m=a.reduce((p,c)=>p+c,0)/a.length; return Math.sqrt(a.reduce((p,c)=>p+(c-m)*(c-m),0)/a.length); }
function mean(a){ return a.reduce((p,c)=>p+c,0)/a.length; }
// donut / arc
function arcPath(cx,cy,rO,rI,a0,a1){
  const p=(r,a)=>[cx+r*Math.cos(a), cy+r*Math.sin(a)];
  const [x0,y0]=p(rO,a0),[x1,y1]=p(rO,a1),[x2,y2]=p(rI,a1),[x3,y3]=p(rI,a0);
  const large=(a1-a0)>Math.PI?1:0;
  return `M${x0} ${y0} A${rO} ${rO} 0 ${large} 1 ${x1} ${y1} L${x2} ${y2} A${rI} ${rI} 0 ${large} 0 ${x3} ${y3} Z`;
}
