function syRamp(t,st){t=Math.max(0,Math.min(1,t));var n=st.length-1;var seg=Math.min(n-1,Math.floor(t*n));var lt=t*n-seg;var a=st[seg],b=st[seg+1];return 'rgb('+lerp(a[0],b[0],lt)+','+lerp(a[1],b[1],lt)+','+lerp(a[2],b[2],lt)+')';}
const SY_AGE=[[250,232,86],[38,190,190],[54,106,214]], SY_HDI=[[255,206,74],[224,74,150],[132,58,196]];  // flipped: young=yellow→old=blue, lowHDI=gold→highHDI=violet
function buildSeeYourself(scene){
  const S=SEEYOU, CONTS=S.continents, you=S.you;
  const ACC=(cssv('--accent')||'#2997ff'), MUT=(cssv('--ink3')||'#86868b');
  const DIS=(typeof SY_DIS!=='undefined'&&SY_DIS)?SY_DIS.diseases:{};
  const DIS_H='#5b9bd5', DIS_D='#e0655c';   // healthy / disease dot colours
  head(scene,'The global ordination','The most diverse human gut microbiome dataset <em>to date</em> (70 countries)',
    'A continent-balanced sample of '+S.n.pcoa.toLocaleString()+' gut microbiomes, drawn from the full '+S.n.cohortGut.toLocaleString()+'-sample HMToL collection. Recolour the ordination by geography, development or age — then see how phylogenetic diversity moves across the human lifespan.');

  /* Figure A: unweighted-UniFrac PCoA */
  const gA=glass(); gA.style.position='relative';
  gA.innerHTML='<div class="kicker">Unweighted UniFrac · Greengenes2 phylogeny</div>'+
    '<h3 class="fig-h">Where the samples land in the ordination</h3>'+
    '<div class="segbar" role="group" aria-label="Colour by">'+['Hemisphere','HDI','Age'].map(function(m,i){return '<button data-m="'+m.toLowerCase()+'"'+(i===2?' class="on"':'')+'>'+m+'</button>';}).join('')+''+'</div>';
  const scr=document.createElement('div'); scr.className='chart-scroll'; gA.appendChild(scr);
  const legA=document.createElement('div'); legA.className='legend'; gA.appendChild(legA);
  const capA=document.createElement('div'); capA.className='caption'; capA.innerHTML='<b>What this shows:</b> each dot is a real gut sample placed by unweighted UniFrac (phylogenetic community difference). This is a continent-balanced random subsample of '+S.n.pcoa.toLocaleString()+' (from '+S.n.cohortGut.toLocaleString()+'), so continents are equal-sized by design and dot density is not proportional to real sampling. Your amber marker is your sample; tap or hover a dot for its details.'; gA.appendChild(capA);
  const tipA=document.createElement('div'); tipA.className='sy-tip'; gA.appendChild(tipA);
  const W=660,Hh=480,mL=52,mR=16,mT=14,mB=44; let mode='age';
  const AP=S.points.concat([you]);
  const xsc=scaleLinear([Math.min.apply(null,AP.map(function(p){return p.x;})),Math.max.apply(null,AP.map(function(p){return p.x;}))],[mL,W-mR]);
  const ysc=scaleLinear([Math.min.apply(null,AP.map(function(p){return p.y;})),Math.max.apply(null,AP.map(function(p){return p.y;}))],[Hh-mB,mT]);
  function frac(v,lo,hi){var s=hi-lo;return s?(v-lo)/s:0.5;}
  function colOf(p){
    if(mode==='hemisphere') return p.h===1?SY_HEMI_N:(p.h===0?SY_HEMI_S:MUT);
    if(mode==='age') return p.a==null?MUT:syRamp(frac(p.a,S.ranges.age[0],S.ranges.age[1]),SY_AGE);
    return p.d==null?MUT:syRamp(frac(p.d,S.ranges.hdi[0],S.ranges.hdi[1]),SY_HDI);
  }
  function legHtml(){
    var yk='<span class="key you-key"><span class="swatch round"></span>You</span>';
    if(mode==='hemisphere') return '<span class="key"><span class="swatch round" style="background:'+SY_HEMI_N+';box-shadow:0 0 0 1px var(--hair2)"></span>Global North</span><span class="key"><span class="swatch round" style="background:'+SY_HEMI_S+';box-shadow:0 0 0 1px var(--hair2)"></span>Global South</span>'+yk;
    var isAge=mode==='age', rr=isAge?S.ranges.age:S.ranges.hdi, st=isAge?SY_AGE:SY_HDI, lab=isAge?'Age (yrs)':'HDI';
    var grad=st.map(function(s,i){return 'rgb('+s.join(',')+') '+Math.round(100*i/(st.length-1))+'%';}).join(',');
    var bar='<span class="key"><b style="color:var(--ink2)">'+lab+'</b> <span class="muted">'+rr[0]+'</span><span class="sy-bar" style="background:linear-gradient(90deg,'+grad+')"></span><span class="muted">'+rr[1]+'</span></span>';
    return bar+yk+(isAge?'':'<span class="key" style="color:var(--ink3)">· adults only</span>');
  }
  var INK2=(cssv('--ink2')||'#a1a1a6'), HAIR=(cssv('--hair2')||'#3a3f47');
  function gradStops(st){return st.map(function(v,i){return '<stop offset="'+Math.round(100*i/(st.length-1))+'%" stop-color="rgb('+v.join(',')+')"/>';}).join('');}
  function globeGrid(r){return '<line x1="'+(-r)+'" y1="0" x2="'+r+'" y2="0" stroke="#ffffff55" stroke-width="0.8"/><ellipse cx="0" cy="0" rx="'+(r*0.5).toFixed(1)+'" ry="'+r+'" fill="none" stroke="#ffffff30" stroke-width="0.8"/><ellipse cx="0" cy="0" rx="'+r+'" ry="'+(r*0.42).toFixed(1)+'" fill="none" stroke="#ffffff2a" stroke-width="0.8"/><circle r="'+r+'" fill="none" stroke="#ffffff66" stroke-width="1.2"/>';}
  function person(cx,baseY,h,color){var hr=h*0.26, hcy=baseY-h+hr, top=hcy+hr, wt=h*0.15, wb=h*0.33;
    return '<g fill="'+color+'"><circle cx="'+cx+'" cy="'+hcy.toFixed(1)+'" r="'+hr.toFixed(1)+'"/><path d="M'+(cx-wt).toFixed(1)+' '+top.toFixed(1)+' L'+(cx+wt).toFixed(1)+' '+top.toFixed(1)+' L'+(cx+wb).toFixed(1)+' '+baseY.toFixed(1)+' L'+(cx-wb).toFixed(1)+' '+baseY.toFixed(1)+' Z"/></g>';}
  function flatMap(inner){var MW=196,MH=MW*77.3/364,MX=W*0.5-MW/2,MY=24;
    return {svg:'<svg x="'+MX.toFixed(1)+'" y="'+MY+'" width="'+MW+'" height="'+MH.toFixed(1)+'" viewBox="'+SY_MAP_VB+'" preserveAspectRatio="xMidYMid meet">'+inner+'</svg>', mx:MX,my:MY,mw:MW,mh:MH};}
  function fig(inner,vb,x,baseY,h,color){var p=vb.split(/\s+/),vw=+p[2],vh=+p[3],w=h*vw/vh;
    return '<svg x="'+(x-w/2).toFixed(1)+'" y="'+(baseY-h).toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+h.toFixed(1)+'" viewBox="'+vb+'" fill="'+color+'" style="color:'+color+'">'+inner+'</svg>';}
  function topLegend(m){
    var cx=W*0.5;
    if(m==='hemisphere'){
      var M=flatMap(SY_MAP_NS), ly=M.my+M.mh+15;
      return M.svg+'<g font-size="10" font-weight="700"><rect x="'+(cx-86)+'" y="'+(ly-8)+'" width="7" height="7" rx="1.5" fill="'+SY_HEMI_N+'"/><text x="'+(cx-76)+'" y="'+ly+'" fill="'+SY_HEMI_N+'">Global North</text><rect x="'+(cx+12)+'" y="'+(ly-8)+'" width="7" height="7" rx="1.5" fill="'+SY_HEMI_S+'"/><text x="'+(cx+22)+'" y="'+ly+'" fill="'+SY_HEMI_S+'">Global South</text></g>';
    }
    if(m==='hdi'){
      var M2=flatMap(SY_MAP_HDI), barW=150, bx=cx-barW/2, by=M2.my+M2.mh+13;
      return '<defs><linearGradient id="syHbar" x1="0" x2="1" y1="0" y2="0">'+gradStops(SY_HDI)+'</linearGradient></defs>'+M2.svg+
        '<rect x="'+bx+'" y="'+by+'" width="'+barW+'" height="9" rx="2" fill="url(#syHbar)" stroke="'+HAIR+'" stroke-width="0.5"/>'+
        '<text x="'+bx+'" y="'+(by+22)+'" fill="'+INK2+'" font-size="10.5">low HDI</text>'+
        '<text x="'+(bx+barW)+'" y="'+(by+22)+'" text-anchor="end" fill="'+INK2+'" font-size="10.5">high</text>';
    }
    // AGE: baby (youngest colour) + adult (oldest colour), horizontal age ramp with year labels below
    var yc=syRamp(0,SY_AGE), oc=syRamp(1,SY_AGE), amax=S.ranges.age[1];
    var baseY=92, Ha=66, Hb=40, bxc=cx-76, axc=cx+66;
    var s=fig(SY_BABY,SY_BABY_VB,bxc,baseY,Hb,yc)+fig(SY_ADULT,SY_ADULT_VB,axc,baseY,Ha,oc);
    var barW=176, bxl=cx-barW/2, by=baseY+9;
    s+='<defs><linearGradient id="syAbar" x1="0" x2="1" y1="0" y2="0">'+gradStops(SY_AGE)+'</linearGradient></defs>';
    s+='<rect x="'+bxl+'" y="'+by+'" width="'+barW+'" height="9" rx="2" fill="url(#syAbar)" stroke="'+HAIR+'" stroke-width="0.5"/>';
    var tk=niceTicks(0,amax,5);
    for(var i=0;i<tk.length;i++){var a=tk[i]; if(a<0||a>amax) continue; var tx=bxl+barW*(a/amax);
      s+='<text x="'+tx.toFixed(1)+'" y="'+(by+21)+'" text-anchor="middle" fill="'+INK2+'" font-size="10">'+a+'</text>';}
    s+='<text x="'+cx+'" y="'+(by+34)+'" text-anchor="middle" fill="'+INK2+'" font-size="10.5" font-weight="700">Age (years)</text>';
    return s;
  }
  function shown(p){ if(mode==='age') return p.a!=null; if(mode==='hemisphere'||mode==='hdi') return p.ad===1; return true; }
  var CAP_GLOBAL=capA.innerHTML;
  var curXsc=xsc, curYsc=ysc, curPts=S.points, curShown=shown, curTip=null;
  function drawGlobal(){
    curXsc=xsc; curYsc=ysc; curPts=S.points; curShown=shown;
    curTip=function(p){return '<b>'+(CONTS[p.c]||'—')+'</b>'+(p.a!=null?' · '+p.a+' yr':'')+(p.d!=null?' · HDI '+p.d:'');};
    var s='<svg viewBox="0 0 '+W+' '+Hh+'" role="img" aria-label="UniFrac PCoA of gut samples">';
    s+=axis(xsc,{orient:'bottom',pos:Hh-mB,ticks:niceTicks(xsc.domain[0],xsc.domain[1],5),title:'PC1 ('+S.var[0]+'%)'});
    s+=axis(ysc,{orient:'left',pos:mL,ticks:niceTicks(ysc.domain[0],ysc.domain[1],5),title:'PC2 ('+S.var[1]+'%)'});
    var op=(mode==='hemisphere'?0.85:0.68), pr=(mode==='hemisphere'?3.7:3.2);
    for(var i=0;i<S.points.length;i++){var p=S.points[i];if(!shown(p))continue;s+='<circle cx="'+xsc(p.x).toFixed(1)+'" cy="'+ysc(p.y).toFixed(1)+'" r="'+pr+'" fill="'+colOf(p)+'" fill-opacity="'+op+'"/>';}
    s+=youDot(xsc(you.x),ysc(you.y),7)+youLabel(xsc(you.x),ysc(you.y),'You');
    s+=topLegend(mode);
    s+='</svg>'; scr.innerHTML=s; legA.innerHTML=legHtml(); capA.innerHTML=CAP_GLOBAL;
  }
  function drawDisease(d){
    var pts=d.points, yo=d.you;
    var xs=pts.map(function(p){return p.x;}).concat([yo.x]), ys=pts.map(function(p){return p.y;}).concat([yo.y]);
    var dx=scaleLinear([Math.min.apply(null,xs),Math.max.apply(null,xs)],[mL,W-mR]);
    var dy=scaleLinear([Math.min.apply(null,ys),Math.max.apply(null,ys)],[Hh-mB,mT]);
    curXsc=dx; curYsc=dy; curPts=pts; curShown=function(){return true;};
    curTip=function(p){return '<b>'+(p.g===1?d.display:'Healthy')+'</b>';};
    var s='<svg viewBox="0 0 '+W+' '+Hh+'" role="img" aria-label="UniFrac PCoA '+d.display+'">';
    s+=axis(dx,{orient:'bottom',pos:Hh-mB,ticks:niceTicks(dx.domain[0],dx.domain[1],5),title:'PC1 ('+d.var[0]+'%)'});
    s+=axis(dy,{orient:'left',pos:mL,ticks:niceTicks(dy.domain[0],dy.domain[1],5),title:'PC2 ('+d.var[1]+'%)'});
    for(var i=0;i<pts.length;i++){var p=pts[i];s+='<circle cx="'+dx(p.x).toFixed(1)+'" cy="'+dy(p.y).toFixed(1)+'" r="3.5" fill="'+(p.g===1?DIS_D:DIS_H)+'" fill-opacity="0.72"/>';}
    s+=youDot(dx(yo.x),dy(yo.y),7)+youLabel(dx(yo.x),dy(yo.y),'You');
    s+='</svg>'; scr.innerHTML=s;
    legA.innerHTML='<span class="key"><span class="swatch round" style="background:'+DIS_H+';box-shadow:0 0 0 1px var(--hair2)"></span>Healthy ('+d.nH+')</span>'+
      '<span class="key"><span class="swatch round" style="background:'+DIS_D+';box-shadow:0 0 0 1px var(--hair2)"></span>'+d.display+' ('+d.nD+')</span>'+
      '<span class="key you-key"><span class="swatch round"></span>You</span>';
    capA.innerHTML='<b>What this shows:</b> a standalone unweighted-UniFrac PCoA of the '+d.cite+' cohort — '+d.nH+' healthy vs '+d.nD+' '+d.display.toLowerCase()+' gut samples, all mapped to the same Greengenes2 tree. Your amber marker is placed in the same ordination. Because your sample comes from a different HMTOL study, its position reflects cohort and geography as much as disease — this is an exploratory view, not a diagnosis.';
  }
  function drawA(){var d=DIS[mode]; var h=gA.querySelector('.fig-h'); if(h) h.textContent=d?(d.display+' — '+d.cite):'Where the samples land in the ordination'; if(d) drawDisease(d); else drawGlobal();}
  gA.querySelector('.segbar').addEventListener('click',function(e){var b=e.target.closest('[data-m]');if(!b)return;mode=b.dataset.m;var bs=gA.querySelectorAll('.segbar button');for(var i=0;i<bs.length;i++)bs[i].classList.toggle('on',bs[i]===b);drawA();});
  function hovA(e){var svg=scr.querySelector('svg');if(!svg)return;var r=svg.getBoundingClientRect();var px=(e.clientX-r.left)/r.width*W,py=(e.clientY-r.top)/r.height*Hh;var best=null,bd=1e9;for(var i=0;i<curPts.length;i++){var p=curPts[i];if(curShown&&!curShown(p))continue;var dxv=curXsc(p.x)-px,dyv=curYsc(p.y)-py,dd=dxv*dxv+dyv*dyv;if(dd<bd){bd=dd;best=p;}}var gr=gA.getBoundingClientRect();if(best&&bd<170){tipA.innerHTML=curTip?curTip(best):'';tipA.style.opacity='1';var tw=tipA.offsetWidth||140;var lx=Math.max(4,Math.min(gA.clientWidth-tw-4,(e.clientX-gr.left)+12));tipA.style.left=lx+'px';tipA.style.top=((e.clientY-gr.top)-4)+'px';}else tipA.style.opacity='0';}
  scr.addEventListener('pointermove',hovA);scr.addEventListener('pointerdown',hovA);scr.addEventListener('pointerleave',function(){tipA.style.opacity='0';});
  drawA(); scene.appendChild(gA);

  /* Figure B: Faith PD across the lifespan */
  const gB=glass(); gB.style.marginTop='20px'; gB.style.position='relative';
  gB.innerHTML='<div class="kicker">Faith’s phylogenetic diversity</div><h3 class="fig-h">Phylogenetic diversity across the human lifespan</h3>';
  const chip=document.createElement('div'); chip.className='chipbar';
  chip.innerHTML=['All'].concat(CONTS.filter(function(c){return c!=='Australia';})).map(function(c,i){return '<button data-c="'+c+'"'+(i===0?' class="on"':'')+'>'+c+'</button>';}).join('');
  gB.appendChild(chip);
  const scrB=document.createElement('div'); scrB.className='chart-scroll'; gB.appendChild(scrB);
  const legB=document.createElement('div'); legB.className='legend'; legB.style.justifyContent='center'; legB.style.marginTop='2px';
  legB.innerHTML='<span class="muted" style="margin-right:4px">Continent:</span>'+CONTS.map(function(c,i){return '<span class="key"><span class="swatch round" style="background:'+SY_CC[i]+'"></span>'+c+'</span>';}).join('');
  gB.appendChild(legB);
  const capB=document.createElement('div'); capB.className='caption'; gB.appendChild(capB);
  const FA=S.faithAge, lines=S.faithLines;
  var fv=FA.map(function(p){return p.f;}).sort(function(a,b){return a-b;}); var FTOP=fv[Math.floor(fv.length*0.97)]||S.ranges.faith[1];
  var di=function(f){return 10*Math.min(f,FTOP)/FTOP;};   // rescale Faith PD to a 0–10 diversity index (axis only)
  const W2=660,H2=430,mL2=52,mR2=14,mT2=14,mB2=92; let filt='All';
  const xB=scaleLinear([0,Math.max(S.ranges.age[1],80)],[mL2,W2-mR2]);
  const yB=scaleLinear([0,10],[H2-mB2,mT2]);
  function drawB(){
    var s='<svg viewBox="0 0 '+W2+' '+H2+'" role="img" aria-label="Diversity index versus age">';
    s+=axis(xB,{orient:'bottom',pos:H2-mB2,ticks:niceTicks(0,xB.domain[1],7),title:'Age (years)'});
    s+=axis(yB,{orient:'left',pos:mL2,ticks:niceTicks(0,10,5),title:'Diversity index (0–10)'});
    for(var i=0;i<FA.length;i++){var p=FA[i];if(p.f>FTOP)continue;var dim=(filt!=='All'&&CONTS[p.c]!==filt);s+='<circle cx="'+xB(p.a).toFixed(1)+'" cy="'+yB(di(p.f)).toFixed(1)+'" r="2.5" fill="'+(dim?MUT:(SY_CC[p.c]||MUT))+'" fill-opacity="'+(dim?0.1:0.55)+'"/>';}
    var ln=lines[filt]||lines.All;
    if(ln&&ln.length>1){var d='M'+ln.map(function(pt){return xB(pt.a).toFixed(1)+' '+yB(di(pt.f)).toFixed(1);}).join(' L');s+='<path d="'+d+'" fill="none" stroke="'+ACC+'" stroke-width="2.6"/>';for(var j=0;j<ln.length;j++){s+='<circle cx="'+xB(ln[j].a).toFixed(1)+'" cy="'+yB(di(ln[j].f)).toFixed(1)+'" r="3" fill="'+ACC+'"/>';}}
    s+='<g opacity="0.95">'+fig(SY_BABY,SY_BABY_VB,mL2+30,H2-10,42,syRamp(0,SY_AGE))
      +fig(SY_ADULT,SY_ADULT_VB,W2-mR2-34,H2-10,60,syRamp(1,SY_AGE))+'</g>';
    s+='</svg>'; scrB.innerHTML=s;
    var la=lines[filt]||lines.All||[];
    var reg=(filt==='All'?'global':filt), body;
    if(la.length<2) body='there are too few '+reg+' samples spread across ages to draw a lifespan median.';
    else { var lo=la[0], hi=la[la.length-1]; body='the '+reg+' median climbs from <b>'+di(lo.f).toFixed(1)+'</b> in the youngest age band to <b>'+di(hi.f).toFixed(1)+'</b> in the oldest.'; }
    capB.innerHTML='<b>What this shows:</b> phylogenetic diversity (Faith’s PD, rescaled to a 0–10 index) for real gut samples across the lifespan; the blue line is the median per age band for the selected region. Samples over 10 yr with very low diversity are filtered out. Here, '+body+' Use the chips to filter by continent.';
  }
  chip.addEventListener('click',function(e){var b=e.target.closest('[data-c]');if(!b)return;filt=b.dataset.c;var bs=chip.querySelectorAll('button');for(var i=0;i<bs.length;i++)bs[i].classList.toggle('on',bs[i]===b);drawB();});
  drawB(); scene.appendChild(gB);
}

